				toolName: "edit",
				text: "Successfully replaced 3000 block(s) in src/big.ts.",
				details: { diff: "", patch, firstChangedLine: 1 },
			}),
		]).transcriptLineCount();

		expect(count).toBeLessThan(400);
	});

	test("rendering a finished agent twice produces identical output", async () => {
